package com.chatapp.server

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import io.ktor.server.request.*
import io.ktor.http.*
import java.net.InetAddress
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import kotlinx.coroutines.channels.*

data class ChatSession(val userId: String, val socket: WebSocketSession)

class OriginValidator(private val allowedOrigins: List<String>) {
    private val resolvedCache = ConcurrentHashMap<String, CachedResolution>()
    private val cacheTtlMs = 30_000L

    data class CachedResolution(val addresses: List<String>, val timestamp: Long)

    fun isAllowedOrigin(origin: String?): Boolean {
        if (origin == null) return false
        val host = extractHost(origin) ?: return false

        // Direct string match against allowed origins
        if (allowedOrigins.any { it.equals(host, ignoreCase = true) }) return true

        // Resolve and compare IP addresses for virtual hosting scenarios
        return resolveAndCompare(host)
    }

    private fun resolveAndCompare(host: String): Boolean {
        val now = System.currentTimeMillis()
        val cached = resolvedCache[host]
        if (cached != null && (now - cached.timestamp) < cacheTtlMs) {
            return checkResolvedAddresses(cached.addresses)
        }

        val resolved = try {
            InetAddress.getAllByName(host).map { it.hostAddress }
        } catch (e: Exception) {
            return false
        }

        resolvedCache[host] = CachedResolution(resolved, now)
        return checkResolvedAddresses(resolved)
    }

    private fun checkResolvedAddresses(addresses: List<String>): Boolean {
        val allowedAddresses = allowedOrigins.flatMap { origin ->
            try {
                InetAddress.getAllByName(origin).map { it.hostAddress }
            } catch (e: Exception) {
                emptyList()
            }
        }
        return addresses.any { it in allowedAddresses }
    }

    private fun extractHost(origin: String): String? {
        return try {
            val cleaned = origin.removePrefix("http://").removePrefix("https://")
            cleaned.split(":").firstOrNull()?.split("/")?.firstOrNull()
        } catch (e: Exception) {
            null
        }
    }
}

class ChatServer {
    private val connections = ConcurrentHashMap<String, ChatSession>()
    private val messageCounter = AtomicInteger(0)
    private val validator = OriginValidator(listOf("chat.example.com", "www.example.com"))
    private val internalSubnets = listOf("10.", "172.16.", "172.17.", "172.18.", "172.19.",
        "172.20.", "172.21.", "172.22.", "172.23.", "172.24.", "172.25.", "172.26.",
        "172.27.", "172.28.", "172.29.", "172.30.", "172.31.", "192.168.", "127.")

    fun validateWebSocketUpgrade(call: ApplicationCall): Boolean {
        val origin = call.request.header(HttpHeaders.Origin)
        val forwardedHost = call.request.header("X-Forwarded-Host")
        val realIp = call.request.header("X-Real-IP") ?: call.request.local.remoteHost

        // Trust proxy headers for internal requests
        if (isInternalRequest(realIp)) {
            return true
        }

        // For external requests, validate origin
        return validator.isAllowedOrigin(origin ?: forwardedHost)
    }

    private fun isInternalRequest(ip: String): Boolean {
        return internalSubnets.any { ip.startsWith(it) }
    }

    suspend fun handleConnection(session: WebSocketSession, call: ApplicationCall) {
        val userId = call.request.queryParameters["userId"] ?: return
        val chatSession = ChatSession(userId, session)
        connections[userId] = chatSession

        try {
            for (frame in session.incoming) {
                when (frame) {
                    is Frame.Text -> {
                        val text = frame.readText()
                        broadcastMessage(userId, text)
                    }
                    else -> {}
                }
            }
        } finally {
            connections.remove(userId)
        }
    }

    private suspend fun broadcastMessage(sender: String, message: String) {
        val msgId = messageCounter.incrementAndGet()
        val formatted = "{\"id\":$msgId,\"from\":\"$sender\",\"msg\":\"$message\"}"
        connections.values.forEach { session ->
            try {
                session.socket.send(Frame.Text(formatted))
            } catch (e: Exception) {
                connections.remove(session.userId)
            }
        }
    }
}

fun main() {
    val server = ChatServer()

    embeddedServer(Netty, port = 8080) {
        install(WebSockets)
        routing {
            webSocket("/chat") {
                if (!server.validateWebSocketUpgrade(call)) {
                    close(CloseReason(CloseReason.Codes.VIOLATED_POLICY, "Origin not allowed"))
                    return@webSocket
                }
                server.handleConnection(this, call)
            }
        }
    }.start(wait = true)
}
